## Code Example

```javascript
interface RetryPolicy {
  nextDelay(attempt: number, error: Error, context: any): number;
}
class ConstantBackoff implements RetryPolicy {
  constructor(private delay: number) {}
  nextDelay(attempt: number) { return this.delay; }
}
class ExponentialBackoff implements RetryPolicy {
  constructor(private base: number, private factor: number) {}
  nextDelay(attempt: number) { return this.base * Math.pow(this.factor, attempt - 1); }
}
class Registry<K, V> {
  private map = new Map<K, V>();
  register(key: K, policy: V) { this.map.set(key, policy); }
  get(key: K): V | undefined { return this.map.get(key); }
}
```

